const corr_serie = context.panel.data.series[0]
const metric1 = corr_serie.fields.find((f) => f.name === 'metric1').values;
const metric2 = corr_serie.fields.find((f) => f.name === 'metric2').values;
const value = corr_serie.fields.find((f) => f.name === 'value').values;
const ec_data = value.map((v, i) => [
  metric1[i],
  metric2[i],
  v.toFixed(3)
]).concat(value.map((v, i) => [
  metric2[i],
  metric1[i],
  v.toFixed(3)
])).concat(value.map((mc1, i) => [
  metric1[i],
  metric1[i],
  '-'
]));

ec_data.sort(([m1, m2], [n1, n2]) => (m1 + m2).localeCompare(n1 + n2))

function correlationDescriptionEvans96(rawValue) {
  let value = Math.abs(rawValue);
  let desc = "";
  if (value == 0) {
    desc = "no";
  } else if (value > 0 && value < 0.2) {
    desc = "very weak";
  } else if (value >= 0.2 && value < 0.4) {
    desc = "weak";
  } else if (value >= 0.4 && value < 0.6) {
    desc = "moderate";
  } else if (value >= 0.6 && value < 0.8) {
    desc = "strong";
  } else if (value > 0.8 && value < 1) {
    desc = "very strong";
  } else if (value == 1) {
    desc = "perfect";
  }
  let sign = rawValue >= 0 ? "positive" : "negative";
  return `${desc} ${sign} correlation`;
}


return {
  backgroundColor: 'transparent',
  tooltip: {
    formatter: ({ marker, data }) => `${data[0]} vs ${data[1]}
<br/>${marker} : ${data[2]} ${correlationDescriptionEvans96(Number.parseFloat(data[2]))}`,
  },
  toolbox: {
    feature: {
      dataZoom: {
        yAxisIndex: 'none',
        icon: {
          zoom: 'path://',
          back: 'path://',
        },
      },
      saveAsImage: {},
    }
  },
  xAxis: {
    type: 'category',
    axisLabel: {
      rotate: 45,
    }
  },
  yAxis: {
    type: 'category',
    inverse: true
  },
  visualMap: {
    min: -1,
    max: 1,
    calculable: true,
    realtime: true,
    inRange: {
      color: [
        '#313695',
        '#4575b4',
        '#74add1',
        '#abd9e9',
        '#e0f3f8',
        '#ffffbf',
        '#fee090',
        '#fdae61',
        '#f46d43',
        '#d73027',
        '#a50026'
      ]
    }
  },
  grid: {
    left: '2%',
    right: '2%',
    top: '2%',
    bottom: 24,
    containLabel: true,
  },
  series: {
    name: "corr",
    type: 'heatmap',
    data: ec_data,
    label: {
      show: true
    },
    emphasis: {
      itemStyle: {
        shadowBlur: 10,
        shadowColor: 'rgba(0, 0, 0, 0.5)'
      }
    }
  },
};

